SELECT analytics_budget_facts.expense_category, AVG(analytics_budget_facts.budget_variance_pct) AS budget_variance_pct FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2024 AND analytics_budget_facts.month = 4 AND analytics_budget_facts.department = 'department_03' AND analytics_budget_facts.cost_center = 'cc_018' GROUP BY analytics_budget_facts.expense_category ORDER BY budget_variance_pct DESC, analytics_budget_facts.expense_category ASC LIMIT 12
